818	+/**
819	+ * @brief 把坏掉的 LFS 挂载点重新挂上（哪个坏挂哪个）。
820	+ *
821	+ * @details 只在"**卡还能读**但 LFS 用不了"时才动手 —— 门就是用 FAT 探的，
822	+ *          理由同上：FAT 与 LFS 同卡，FAT 能读说明卡没坏，那问题就在 LFS
823	+ *          实例上（硬复位救回卡之后 LittleFS 的 RAM 内状态不会自愈，必须重挂）。
824	+ *          卡读不到时直接返回，把舞台留给 SD 层的判死/硬复位。
825	+ *
826	+ *          两个坑，都踩过：
827	+ *          1. /mnt/kv **不能**直接重调 sf32lb_sd_mount_kv()——它开头
828	+ *             `if (g_sd_kv_mtd != NULL) return OK;` 会立刻返回成功却根本不重挂。
829	+ *             所以这里走 umount + 按设备名 mount，不重复注册 MTD。
830	+ *          2. kv 的开机挂载带 "autoformat"；恢复路径上**刻意不传**，而且
831	+ *             按"LFS 永不格式化"的要求，开机那条也要去掉（见 mount_kv）。
832	+ *
833	+ *          不要在持有 SD 总线锁的路径里调用：mount 内部还要走 SD I/O，
834	+ *          g_sd_lock 不可重入，会自锁。只从 diag 线程调。
835	+ *
836	+ * @return 0 全部可用（含本次修好的）；-EAGAIN 卡读不到；负 errno 为失败。
837	+ */
838	+int sf32lb_sd_fs_heal(void)
839	+{
840	+  struct statfs st;
841	+  int ret = 0;
842	+  int one;
843	+
844	+  if (statfs(SF32LB_SD_FAT_MOUNTPOINT, &st) != 0)
845	+    {
846	+      syslog(LOG_WARNING, "LFS: heal skipped, card not readable via %s (SD layer owns it)\n",
847	+             SF32LB_SD_FAT_MOUNTPOINT);
848	+      return -EAGAIN;
849	+    }
850	+
851	+  if (statfs(SF32LB_SD_MOUNTPOINT, &st) != 0)
852	+    {
853	+      syslog(LOG_WARNING, "LFS: remount %s (card readable, FS is not)\n",
854	+             SF32LB_SD_MOUNTPOINT);
855	+      (void)umount(SF32LB_SD_MOUNTPOINT);
856	+      one = sf32lb_sd_mount_littlefs(0);
857	+      syslog(one == 0 ? LOG_WARNING : LOG_ERR,
858	+             "LFS: remount %s ret=%d\n", SF32LB_SD_MOUNTPOINT, one);
859	+      if (one != 0)
860	+        {
861	+          ret = one;
862	+        }
863	+    }
864	+
865	+  if (statfs(SF32LB_SD_KV_MOUNTPOINT, &st) != 0)
866	+    {
867	+      syslog(LOG_WARNING, "LFS: remount %s (card readable, FS is not)\n",
868	+             SF32LB_SD_KV_MOUNTPOINT);
869	+      (void)umount(SF32LB_SD_KV_MOUNTPOINT);
870	+      one = mount(SF32LB_SD_KV_DEV, SF32LB_SD_KV_MOUNTPOINT, "littlefs",
871	+                  0, NULL);
872	+      syslog(one == 0 ? LOG_WARNING : LOG_ERR,
873	+             "LFS: remount %s ret=%d errno=%d\n",
874	+             SF32LB_SD_KV_MOUNTPOINT, one, errno);
875	+      if (one != 0 && ret == 0)
876	+        {
877	+          ret = -errno;
878	+        }
879	+    }
880	+
881	+  return ret;
882	+}
