1729	static int sf32lb_sd_read_block_retry(uint64_t card_byte_addr,
1730	                                      FAR uint8_t *dst)
1731	{
1732	  int ret;
1733	  int t;
1734	
1735	  if (sd1_dead_fail_fast())
1736	    {
1737	      return -EIO;
1738	    }
1739	
1740	  ret = sf32lb_sd_read_block(card_byte_addr, dst);
1741	  if (ret >= 0)
1742	    {
1743	      sd1_restore_tran_clock();
1744	      return ret;
1745	    }
1746	
1747	  /* Retry at the current clock first (official does not downclock on a
1748	   * single glitch).  Drop to 6 MHz only after those retries fail, then
1749	   * restore TRAN on success.
1750	   */
1751	
1752	  for (t = 1; t <= SF32LB_SD_IO_RETRIES; t++)
1753	    {
1754	      g_sd_diag.rd_retry++;
1755	      sd1_recover_after_error();
1756	      ret = sf32lb_sd_read_block(card_byte_addr, dst);
1757	      if (ret >= 0)
1758	        {
1759	          sd1_restore_tran_clock();
1760	          syslog(LOG_WARNING, "SD: read addr=0x%llx recovered at %u kHz "
1761	                 "(try %d)\n", (unsigned long long)card_byte_addr,
1762	                 (unsigned)(g_sd_bus_hz / 1000), t);
1763	          return ret;
1764	        }
1765	    }
1766	
1767	  sd1_set_clock(SF32LB_SD_RETRY_CLOCK_HZ);
1768	  g_sd_bus_hz = SF32LB_SD_RETRY_CLOCK_HZ;
1769	  sd1_recover_after_error();
1770	  ret = sf32lb_sd_read_block(card_byte_addr, dst);
1771	  if (ret >= 0)
1772	    {
1773	      sd1_restore_tran_clock();
1774	      syslog(LOG_WARNING,
1775	             "SD: read addr=0x%llx recovered at 6 MHz then restored\n",
1776	             (unsigned long long)card_byte_addr);
1777	      return ret;
1778	    }
1779	
1780	  g_sd_diag.rd_fail++;
1781	  if (g_sd_fail_run < 0xffffu)
1782	    {
1783	      g_sd_fail_run++;
1784	    }
1785	  /* 把"连续第几次失败 / 当前总线时钟 / 累计重试"一起打出来，用来区分
1786	   * 概率性抖动与永久性损坏：
1787	   *   - run 每次失败都递增、成功即归零 ⇒ 抖动（单次故障）；
1788	   *   - run 单调递增且 clk 一直停在 retry 档 ⇒ 永久性（卡已不应答）。
1789	   * 现场只看单条 FAILED 日志分不出这两种，也看不出时钟是否已经掉档。 */
1790	  syslog(LOG_ERR,
1791	         "SD: read addr=0x%llx FAILED (tries=%d rca=0x%04x run=%u clk=%ukHz sr=0x%08lx why=%s rd_retry=%lu rd_fail=%lu)\n",
1792	         (unsigned long long)card_byte_addr, SF32LB_SD_IO_RETRIES + 1,
1793	         g_sd_rca, (unsigned)g_sd_fail_run, (unsigned)(g_sd_bus_hz / 1000),
1794	         (unsigned long)g_sd_last_sr, sd1_sr_why(g_sd_last_sr),
1795	         (unsigned long)g_sd_diag.rd_retry,
1796	         (unsigned long)g_sd_diag.rd_fail);
1797	  if (sd1_reinit_card() == 0)
1798	    {
1799	      ret = sf32lb_sd_read_block(card_byte_addr, dst);
1800	      if (ret >= 0)
1801	        {
1802	          sd1_restore_tran_clock();
1803	          syslog(LOG_WARNING,
1804	                 "SD: read addr=0x%llx recovered after re-identify\n",
1805	                 (unsigned long long)card_byte_addr);
1806	        }
1807	    }
1808	
1809	  return ret;
1810	}
