1812	static int sf32lb_sd_write_block_retry(uint64_t card_byte_addr,
1813	                                       FAR const uint8_t *src)
1814	{
1815	  uint32_t crc0 = g_sd_diag.wr_crc;
1816	  int ret;
1817	  int t;
1818	
1819	  if (sd1_dead_fail_fast())
1820	    {
1821	      return -EIO;
1822	    }
1823	
1824	  ret = sf32lb_sd_write_block(card_byte_addr, src);
1825	  if (ret >= 0)
1826	    {
1827	      sd1_restore_tran_clock();
1828	      return ret;
1829	    }
1830	
1831	  /* CRC: sampling glitch → drop the clock.  Timeout: DAT0-busy / aborted
1832	   * program; downclocking does not help and the old "stay at 6 MHz" path
1833	   * made sequential LittleFS flushes crawl.
1834	   */
1835	
1836	  if (g_sd_diag.wr_crc > crc0)
1837	    {
1838	      sd1_set_clock(SF32LB_SD_RETRY_CLOCK_HZ);
1839	      g_sd_bus_hz = SF32LB_SD_RETRY_CLOCK_HZ;
1840	    }
1841	
1842	  for (t = 1; t <= SF32LB_SD_IO_RETRIES; t++)
1843	    {
1844	      g_sd_diag.wr_retry++;
1845	      sd1_recover_after_error();
1846	      ret = sf32lb_sd_write_block(card_byte_addr, src);
1847	      if (ret >= 0)
1848	        {
1849	          break;
1850	        }
1851	
1852	      if (g_sd_diag.wr_crc > crc0)
1853	        {
1854	          sd1_set_clock(SF32LB_SD_RETRY_CLOCK_HZ);
1855	          g_sd_bus_hz = SF32LB_SD_RETRY_CLOCK_HZ;
1856	        }
1857	    }
1858	
1859	  if (ret >= 0)
1860	    {
1861	      sd1_restore_tran_clock();
1862	      syslog(LOG_WARNING,
1863	             "SD: write addr=0x%llx recovered clk=%u kHz try=%d sr=0x%lx "
1864	             "cmd_to=%lu wr_to=%lu wr_crc=%lu dat0_to=%lu\n",
1865	             (unsigned long long)card_byte_addr,
1866	             (unsigned)(g_sd_bus_hz / 1000), t,
1867	             (unsigned long)g_sd_last_sr,
1868	             (unsigned long)g_sd_diag.cmd_timeout,
1869	             (unsigned long)g_sd_diag.wr_timeout,
1870	             (unsigned long)g_sd_diag.wr_crc,
1871	             (unsigned long)g_sd_diag.dat0_to);
1872	    }
1873	  else
1874	    {
1875	      g_sd_diag.wr_fail++;
1876	      syslog(LOG_ERR,
1877	             "SD: write addr=0x%llx FAILED after %d tries "
1878	             "(rca=0x%04x clk=%u kHz sr=0x%lx)\n",
1879	             (unsigned long long)card_byte_addr, SF32LB_SD_IO_RETRIES + 1,
1880	             g_sd_rca, (unsigned)(g_sd_bus_hz / 1000),
1881	             (unsigned long)g_sd_last_sr);
1882	      sf32lb_sd_diag_dump("write-fail");
1883	      if (sd1_reinit_card() == 0)
1884	        {
1885	          ret = sf32lb_sd_write_block(card_byte_addr, src);
1886	          if (ret >= 0)
1887	            {
1888	              sd1_restore_tran_clock();
1889	              syslog(LOG_WARNING,
1890	                     "SD: write addr=0x%llx recovered after re-identify\n",
1891	                     (unsigned long long)card_byte_addr);
1892	            }
1893	        }
1894	    }
1895	
1896	  return ret;
1897	}
