2453	static bool sf32lb_sd_in_window(uint64_t rel_off, uint64_t len,
2454	                                FAR const struct sf32lb_sd_dev_s *priv)
2455	{
2456	  return (len > 0) && (rel_off + len <= priv->byte_limit);
