2459	static void sf32lb_sd_bus_lock(bool kv_prio)
2460	{
2461	  if (kv_prio)
2462	    {
2463	      atomic_add(&g_sd_kv_waiters, 1);
2464	      nxmutex_lock(&g_sd_lock);
2465	      atomic_sub(&g_sd_kv_waiters, 1);
2466	      return;
2467	    }
2468	
2469	  nxmutex_lock(&g_sd_lock);
2470	  while (atomic_read(&g_sd_kv_waiters) > 0)
2471	    {
2472	      nxmutex_unlock(&g_sd_lock);
2473	      sched_yield();
2474	      nxmutex_lock(&g_sd_lock);
2475	    }
2476	}
