2483	/* First mkdir / O_CREAT after mounting a packed volume runs lfs_alloc()
2484	 * and can walk the tree for seconds with no sched_yield. bringup is prio
2485	 * 240 > iwdg_feed 180, so work_beat timestamps never become KEEPALIVE.
2486	 * Pet the IWDT register here (lock already dropped). Do not usleep:
2487	 * that 10 ms/s on every bread also runs during map/MTP and let lcd_hw
2488	 * Init at 48 MHz before hclk240 (garbled panel). */
2489	static void sf32lb_sd_io_progress(void)
2490	{
2491	  myvendor_watchdog_work_beat();
2492	  myvendor_watchdog_hw_pet();
2493	}
