2495	static ssize_t sf32lb_sd_bread(FAR struct mtd_dev_s *dev, off_t startblock,
2496	                               size_t nblocks, FAR uint8_t *buffer)
2497	{
2498	  FAR struct sf32lb_sd_dev_s *priv = (FAR struct sf32lb_sd_dev_s *)dev;
2499	  uint64_t byte_off;
2500	  int ret;
2501	
2502	  if (startblock < 0 ||
2503	      !sf32lb_sd_in_window((uint64_t)startblock * priv->page_size,
2504	                           (uint64_t)nblocks * priv->page_size, priv))
2505	    {
2506	      return -EINVAL;
2507	    }
2508	
2509	#if SF32LB_SD_PROFILE
2510	  g_sd_stats.bread++;
2511	  g_sd_stats.bread_pages += nblocks;
2512	#endif
2513	
2514	  byte_off = (uint64_t)priv->byte_offset +
2515	             (uint64_t)startblock * priv->page_size;
2516	  sf32lb_sd_bus_lock(priv->kv_prio);
2517	  ret = sf32lb_sd_read_region(byte_off, buffer,
2518	                              (uint32_t)nblocks * priv->page_size);
