2553	static int sf32lb_sd_erase(FAR struct mtd_dev_s *dev, off_t startblock,
2554	                           size_t nblocks)
2555	{
2556	  FAR struct sf32lb_sd_dev_s *priv = (FAR struct sf32lb_sd_dev_s *)dev;
2557	  uint64_t byte_off;
2558	  uint32_t nbytes;
2559	  int ret = OK;
2560	
2561	  if (startblock < 0 ||
2562	      !sf32lb_sd_in_window((uint64_t)startblock * priv->erase_size,
2563	                           (uint64_t)nblocks * priv->erase_size, priv))
2564	    {
2565	      return -EINVAL;
2566	    }
2567	
2568	  /* SD/eMMC has no hardware erase, but LittleFS relies on an erased block
2569	   * reading back as 0xFF (its metadata-log scan stops at the first non-CRC /
2570	   * erased entry). Stale data would let an old commit validate and corrupt the
2571	   * FS, so fill the erase block with 0xFF — matching scripts/mklfs_disk and the
2572	   * NAND erase semantics.
2573	   */
2574	
2575	#if SF32LB_SD_PROFILE
2576	  g_sd_stats.erase_blocks += nblocks;
2577	#endif
2578	
2579	  byte_off = (uint64_t)priv->byte_offset +
2580	             (uint64_t)startblock * priv->erase_size;
2581	  nbytes = (uint32_t)nblocks * priv->erase_size;
2582	
2583	  sf32lb_sd_bus_lock(priv->kv_prio);
2584	  memset(g_sd_blkbuf, 0xff, sizeof(g_sd_blkbuf));
2585	  while (nbytes >= SD_HW_BLOCK_SIZE)
2586	    {
2587	      int t;
2588	
2589	      for (t = 0, ret = -EIO; t <= SF32LB_SD_IO_RETRIES; t++)
2590	        {
2591	          ret = sf32lb_sd_program_staged(byte_off);
2592	          if (ret >= 0)
2593	            {
2594	              break;
2595	            }
2596	
2597	          sd1_recover_after_error();
2598	        }
2599	
2600	      if (ret < 0)
2601	        {
2602	          break;
2603	        }
2604	
2605	      byte_off += SD_HW_BLOCK_SIZE;
2606	      nbytes -= SD_HW_BLOCK_SIZE;
2607	    }
2608	
2609	  sf32lb_sd_bus_unlock();
2610	  sf32lb_sd_io_progress();
2611	  return ret < 0 ? ret : (int)nblocks;
2612	}
