2666	/* Re-derive the SD1 divider after HCLK changed. Without this the card would
2667	 * keep running at HCLK/old_div — e.g. 40 MHz once bringup raises HCPU to
2668	 * 240 MHz, well past the 25 MHz SD default-speed limit.

3240	/* Halve the card clock twice and re-measure. If the per-sector cost tracks the
3241	 * clock we are bus-limited (the divider or its source clock is wrong); if it
3242	 * barely moves, the cost is fixed per-CMD17 latency and only multi-block
3243	 * transfers can help.
3244	 */
3245	
3246	static void sf32lb_sd_bench_clocks(FAR struct mtd_dev_s *mtd,
3247	                                   FAR uint8_t *buf)
3248	{
3249	  static const uint32_t hz[] =
3250	  {
3251	    SF32LB_SD_TRAN_CLOCK_HZ,
3252	    SF32LB_SD_TRAN_CLOCK_HZ / 2,
3253	    SF32LB_SD_TRAN_CLOCK_HZ / 4
3254	  };
3255	
3256	  uint32_t hclk = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
3257	  unsigned int i;
3258	
3259	  for (i = 0; i < sizeof(hz) / sizeof(hz[0]); i++)
3260	    {
3261	      uint64_t t0;
3262	      uint64_t dt;
3263	      ssize_t ret = 0;
3264	      uint32_t div;
3265	      int j;
3266	
3267	      nxmutex_lock(&g_sd_lock);
3268	      sd1_set_clock(hz[i]);
3269	      div = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >>
3270	             SD_CLKCR_DIV_Pos) + 1;
3271	      nxmutex_unlock(&g_sd_lock);
3272	
3273	      t0 = sf32lb_sd_now_us();
3274	      for (j = 0; j < 32 && ret >= 0; j++)
3275	        {
3276	          ret = MTD_BREAD(mtd, j, 1, buf);
3277	        }
3278	
3279	      dt = sf32lb_sd_now_us() - t0;
3280	      syslog(LOG_INFO,
3281	             "SDPROF: clk  div=%-3lu (~%lu kHz) %lu us/sector%s\n",
3282	             (unsigned long)div,
3283	             (unsigned long)(hclk / div / 1000),
3284	             (unsigned long)(dt / 32),
3285	             ret < 0 ? " READ FAILED" : "");
3286	    }
3287	
3288	  nxmutex_lock(&g_sd_lock);
3289	  sd1_set_clock(g_sd_bus_hz);
3290	  nxmutex_unlock(&g_sd_lock);
3291	}
