518	  g_applied_mhz = want;
519	  reclock_peripherals();
520	  dll2 = HAL_RCC_HCPU_GetDLL2Freq();
521	  syslog(LOG_INFO,
522	         "dvfs: HCLK=%u MHz holds=0x%x force=%u idle=%u gov=%u "
