704	/**
705	 * @brief PIO 忙等循环的“让出 + 喂狗”节拍器，每 1 ms 触发一次。
706	 *
707	 * @details
708	 * 下面几个等待都是**轮询卡的状态位**（等 DAT0 编程忙、等 DATA_DONE、
709	 * 等 DATA_BUSY），没有中断可用，所以轮询耗掉的时间必然记在发起 I/O 的那个
710	 * 线程头上 —— 这不是"等"、是实打实的 CPU。
711	 *
712	 * 原先只有 `sd1_wait_dat0()` 会 `sched_yield()` + 喂狗，而
713	 * `sd1_wait_write()` / `sd1_wait_card_idle()` 是**纯自旋**，上界
714	 * `SF32LB_SD_WRITE_MAX_US` = 2 s。调用者优先级高于被饿住的那些任务时，
715	 * 这 2 s 里它们一个都跑不到 —— 具体到本板：diag 线程 pri=9 每 500 ms 往
716	 * SD 上的 LittleFS 刷日志（`myvendor_diaglog_flush()`），卡一慢就会把
717	 * `ble_companion`(pri=8) 和 IDLE(0) 饿住。三个等待统一走这个节拍器。
718	 *
719	 * @param[in,out] next_yield 下次让出的时刻；调用方进入循环前初始化一次。
720	 */
721	static void sd1_spin_yield(uint64_t *next_yield)
722	{
723	  uint64_t now = sd1_mono_us();
724	
725	  if (now >= *next_yield)
726	    {
727	      myvendor_watchdog_work_beat();
728	      sched_yield();
729	      *next_yield = now + 1000u;
730	    }
731	}
