733	static uint8_t sd1_wait_dat0(uint64_t timeout_us)
734	{
735	  uint64_t deadline;
736	  uint64_t next_yield;
737	
738	  if (!g_sd_dat0_poll)
739	    {
740	      return SD_SUCCESS;
741	    }
742	
743	  deadline = sd1_mono_us() + timeout_us;
744	  next_yield = sd1_mono_us() + 1000u;
745	  while (!sd1_dat0_ready())
746	    {
747	      uint64_t now = sd1_mono_us();
748	
749	      if (now >= deadline)
750	        {
751	          g_sd_last_sr = hwp_sdmmc1->SR;
752	          g_sd_diag.dat0_to++;
753	          return SD_TIMEOUT;
754	        }
755	
756	      sd1_spin_yield(&next_yield);
757	    }
758	
759	  return SD_SUCCESS;
760	}
