762	static uint8_t sd1_wait_write(void)
763	{
764	  /* Must wait on the error bits too, not just DATA_DONE: on a write CRC or
765	   * data timeout the controller may never assert DATA_DONE, which previously
766	   * spun this loop forever and hung the whole SD-backed filesystem.
767	   */
768	
769	  uint32_t mask = SD_SR_DATA_DONE | SD_SR_DATA_TIMEOUT | SD_SR_DATA_CRC |
770	                  SD_SR_FIFO_UNDERRUN;
771	  uint64_t deadline = sd1_mono_us() + SF32LB_SD_WRITE_MAX_US;
772	  uint64_t next_yield = sd1_mono_us() + 1000u;
773	
774	  while ((hwp_sdmmc1->SR & mask) == 0)
775	    {
776	      if (sd1_mono_us() >= deadline)
777	        {
778	          g_sd_last_sr = hwp_sdmmc1->SR;
779	          hwp_sdmmc1->DCR = 0;
780	          hwp_sdmmc1->SR = 0xffffffff;
781	          g_sd_diag.wr_timeout++;
782	          return SD_TIMEOUT;
783	        }
784	
785	      /* 没有这句就是纯自旋最长 2 s：优先级低于调用者的任务全被饿住。 */
786	      sd1_spin_yield(&next_yield);
787	    }
788	
789	  hwp_sdmmc1->SR = SD_SR_DATA_DONE;
790	  if (hwp_sdmmc1->SR & SD_SR_DATA_TIMEOUT)
791	    {
792	      g_sd_last_sr = hwp_sdmmc1->SR;
793	      g_sd_diag.wr_timeout++;
794	      return SD_TIMEOUT;
795	    }
796	
797	  if (hwp_sdmmc1->SR & (SD_SR_DATA_CRC | SD_SR_FIFO_UNDERRUN))
798	    {
799	      g_sd_last_sr = hwp_sdmmc1->SR;
800	      g_sd_diag.wr_crc++;
801	      return SD_CRCERR;
802	    }
803	
804	  if (sd1_wait_card_idle() != SD_SUCCESS)
805	    {
806	      return SD_TIMEOUT;
807	    }
808	
809	  return sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US);
810	}
