63	/* 落盘门槛：<= 这个级别的行才记。改这一行就能收紧/放宽。
64	 *
65	 * 这里刻意用 WARNING 而不是严格按字面的"只记 error"，因为**恢复过程本身全是
66	 * WARNING**：`SD: hard reset #N`、`SD: still dead after hard reset`、
67	 * `SD: RECOVERED by hard reset`、`SD: re-identify OK`、`LFS: remount`、
68	 * `diag: <slot> unhealthy`、`dvfs: gov re-armed by diag`、`gnss: restart begin`
69	 * —— 而真正的"失败"才是 LOG_ERR（`SD: CMD… FAILED`、`SD: declared DEAD`、
70	 * `LFS: mounted READ-ONLY`）。只留 ERR 会把长测要看的恢复叙事整段丢掉，
71	 * 剩下的只有"坏了"而没有"后来怎么好的"。要严格只留 ERR 就改成 LOG_ERR。 */
72	#define DIAGLOG_MAX_SEV    LOG_WARNING
73	
74	/* 消息前缀里级别记号的样子：vsyslog.c 用 "[%6s] " 配 g_priority_str[]，
75	 * 所以 6 个字符是**右对齐**的（"CRIT"→"[  CRIT]"）。这里按固定字面量匹配，
76	 * 不依赖它在行内的位置 —— 时间戳格式、CPU/TID/PREFIX 开关怎么变都不影响。 */
77	#define DIAGLOG_PFX_MAX    64u       /* 只在前 64 字节里找级别记号 */
78	
79	/* RAM 环。head 是写入位置，tail 是已落盘位置；两者都在环内取模推进。
80	 * 环满时**丢新字节**：日志宁可少几条，也绝不能阻塞或覆盖尚未落盘的部分。
81	 *
82	 * 尺寸刻意取小的 2 KB（"尽量落盘就好，不指望它能做什么"）。用它换算一下能扛多久：
83	 * 实测活跃期日志速率约 2~4 KB/s，而 flush 每个 diag tick（500 ms）一次，
84	 * 所以**环里能留住的是最近约 0.5~1 秒**的内容，超出的最新字节会被丢。
85	 * 真正累积下来的记录是**已经刷进文件的部分** —— 环只决定"刷新之前那零点几秒
86	 * 能丢多少"，不是总容量。刷屏期丢掉最新几行是设计上接受的。
87	 */
88	
89	static char     g_ring[DIAGLOG_RING];
90	static uint32_t g_head;
91	static uint32_t g_tail;
92	
93	static char     g_path[DIAGLOG_PATH_MAX];
94	static int      g_day = -1;          /* 文件名对应的"年内第几天"，用于按天滚动 */
95	static bool     g_started;
96	static bool     g_fail_logged;       /* 落盘失败只报一次，避免自己刷屏 */
97	
98	/****************************************************************************
99	 * 级别过滤：逐行判定
100	 *
101	 * 为什么必须"逐行"而不是"逐次 write"：
102	 *   - `syslog_write_foreach()` 在 CONFIG_SYSLOG_CRLF 下把一条消息拆成
103	 *     "正文"和 "\r\n" **两次** write；
104	 *   - 一条多行消息（`serr("a\nb\n")` 这种）只有**第一行**带级别前缀，
105	 *     续行完全是裸文本。
106	 * 所以规则是：带记号的行走记号的判定，**不带记号的续行继承上一行的判定**。
107	 * 这既保住了多行 Error 的正文，也不会把多行 Info 的续行误收进来。
108	 ****************************************************************************/
109	
110	static const struct diaglog_sev_s
111	{
112	  const char *tok;
113	  int         sev;
114	} g_diaglog_sev[] =
115	{
116	  { "[ EMERG]",  LOG_EMERG   },
117	  { "[ ALERT]",  LOG_ALERT   },
118	  { "[  CRIT]",  LOG_CRIT    },
119	  { "[ ERROR]",  LOG_ERR     },
120	  { "[  WARN]",  LOG_WARNING },
121	  { "[NOTICE]",  LOG_NOTICE  },
122	  { "[  INFO]",  LOG_INFO    },
123	  { "[ DEBUG]",  LOG_DEBUG   },
124	};
125	
126	static char     g_pfx[DIAGLOG_PFX_MAX + 1u]; /* +1：扫描前补 '\0' 供 strstr 用 */
127	static uint8_t  g_pfx_len;
128	static bool     g_decided;               /* 当前行的取舍是否已定 */
129	static bool     g_keep;                  /* 当前行是否要留（下一行未判定时沿用） */
130	static bool     g_in_esc;                /* 正在丢弃一个 ANSI 转义序列 */
131	
132	/* 在前 len 字节里找级别记号；找到返回其级别，找不到返回 -1。
133	 * 匹配的是固定字面量，取**最左**命中（各记号互不为子串，不会有歧义）。
134	 * s 必须是 '\0' 结尾的（调用方在 g_pfx 尾部补过），strstr 才不会越界读。 */
135	static int diaglog_scan_sev(const char *s, size_t len)
136	{
137	  int    best_sev = -1;
138	  size_t best_at  = 0;
139	  size_t i;
140	
141	  (void)len;
142	
143	  for (i = 0; i < sizeof(g_diaglog_sev) / sizeof(g_diaglog_sev[0]); i++)
144	    {
145	      const char *hit = strstr(s, g_diaglog_sev[i].tok);
146	
147	      if (hit != NULL && (best_sev < 0 || (size_t)(hit - s) < best_at))
148	        {
149	          best_at  = (size_t)(hit - s);
150	          best_sev = g_diaglog_sev[i].sev;
151	        }
152	    }
153	
154	  return best_sev;
155	}
156	
157	/* 往环里塞一个字节（环满丢新字节）。调用者须已关中断。 */
158	static void diaglog_ring_putc(char ch)
159	{
160	  uint32_t next = (g_head + 1u) % DIAGLOG_RING;
161	
162	  if (next != g_tail)
163	    {
164	      g_ring[g_head] = ch;
165	      g_head = next;
166	    }
167	}
168	
169	/* 判定当前行：记下取舍，并把已攒下的行首字节按判定落环。调用者须已关中断。 */
170	static void diaglog_decide(bool keep)
171	{
172	  uint8_t i;
173	
174	  g_keep    = keep;
175	  g_decided = true;
176	
177	  if (keep)
178	    {
179	      for (i = 0; i < g_pfx_len; i++)
180	        {
181	          diaglog_ring_putc(g_pfx[i]);
182	        }
183	    }
184	
185	  g_pfx_len = 0;
186	}
187	
188	/* 行结束：下一行重新判定，但 g_keep 留着作为续行的继承值。调用者须已关中断。 */
189	static void diaglog_end_line(void)
190	{
191	  g_decided = false;
192	  g_pfx_len = 0;
193	}
194	
195	/* 一个字节喂进来。整个过滤器的唯一入口，putc/write 两条路都走它。 */
196	static void diaglog_feed(unsigned char ch)
197	{
198	  /* ANSI 转义序列（日志开头有 \e[0m，级别记号前有颜色如 \e[31m）整体丢掉：
199	   * 落盘的文件不需要终端控制码，去掉之后 grep/肉眼都干净。 */
200	  if (g_in_esc)
201	    {
202	      g_in_esc = (ch != 'm');
203	      return;
204	    }
205	
206	  if (ch == 0x1bu)
207	    {
208	      g_in_esc = true;
209	      return;
210	    }
211	
212	  if (g_decided)
213	    {
214	      if (g_keep)
215	        {
216	          diaglog_ring_putc((char)ch);
217	        }
218	
219	      if (ch == '\n')
220	        {
221	          diaglog_end_line();
222	        }
223	
224	      return;
225	    }
226	
227	  /* 还没判定：先攒着行首，攒够或遇到记号为止。 */
228	  if (g_pfx_len < DIAGLOG_PFX_MAX)
229	    {
230	      g_pfx[g_pfx_len++] = (char)ch;
231	      g_pfx[g_pfx_len]   = '\0';   /* strstr 需要结尾 */
232	    }
233	
234	  if (ch == '\n')
235	    {
236	      /* 整行都没出现记号（很短的一行，或非 syslog 直写的裸文本）：
237	       * 按继承值处理，然后收行。 */
238	      diaglog_decide(g_keep);
239	      diaglog_end_line();
240	      return;
241	    }
242	
243	  {
244	    int sev = diaglog_scan_sev(g_pfx, (size_t)g_pfx_len);
245	
246	    if (sev >= 0)
247	      {
248	        diaglog_decide(sev <= DIAGLOG_MAX_SEV);
249	      }
250	    else if (g_pfx_len >= DIAGLOG_PFX_MAX)
251	      {
252	        /* 前缀区都攒满了还没记号：不像是带级别的 syslog 行，按继承值。 */
253	        diaglog_decide(g_keep);
254	      }
255	  }
256	}
257	
258	/****************************************************************************
259	 * 无格式串的路径拼装
260	 ****************************************************************************/
261	
262	/* 把 v 按固定位数（零填充）写进 p，返回新的写指针。v 超出位数时按低位截断。 */
263	
264	static char *diaglog_put_u(char *p, unsigned v, unsigned width)
265	{
266	  unsigned i;
267	
268	  for (i = 0; i < width; i++)
269	    {
270	      unsigned digit = v;
271	      unsigned j;
272	
273	      /* 第 i 位 = v / 10^(width-1-i) 的个位；不用除法表，固定次数循环取。 */
274	      for (j = 0; j < (width - 1u - i); j++)
275	        {
276	          digit /= 10u;
277	        }
278	
279	      p[i] = (char)('0' + (digit % 10u));
280	    }
281	
282	  return p + width;
283	}
284	
285	/* 组一个 dNNN_YYYYMMDD_HHMMSS.txt 名字；seq 是本目录自己的计数器。 */
286	
287	static void diaglog_mkname(char *name, size_t n, unsigned seq, time_t now)
288	{
289	  struct tm tm;
290	  char     *p;
291	
292	  if (n < DIAGLOG_NAME_MAX)
293	    {
294	      name[0] = '\0';
295	      return;
296	    }
297	
298	  localtime_r(&now, &tm);
299	  if (tm.tm_year < 0)
300	    {
301	      memset(&tm, 0, sizeof(tm));
302	    }
303	
304	  p = name;
305	  *p++ = 'd';
306	  p = diaglog_put_u(p, seq % 1000u, 3u);
307	  *p++ = '_';
308	  p = diaglog_put_u(p, (unsigned)(tm.tm_year + 1900), 4u);
309	  p = diaglog_put_u(p, (unsigned)(tm.tm_mon + 1), 2u);
310	  p = diaglog_put_u(p, (unsigned)tm.tm_mday, 2u);
311	  *p++ = '_';
312	  p = diaglog_put_u(p, (unsigned)tm.tm_hour, 2u);
313	  p = diaglog_put_u(p, (unsigned)tm.tm_min, 2u);
314	  p = diaglog_put_u(p, (unsigned)tm.tm_sec, 2u);
315	  memcpy(p, ".txt", 5u);
316	
317	  g_day = tm.tm_yday;
318	}
319	
320	/* 目录 + '/' + 名字。 */
321	
322	static void diaglog_mkpath(char *path, size_t n, const char *name)
323	{
324	  size_t d = strlen(DIAGLOG_DIR);
325	
326	  if (d + 1u + strlen(name) + 1u > n)
327	    {
328	      path[0] = '\0';
329	      return;
330	    }
331	
332	  memcpy(path, DIAGLOG_DIR, d);
333	  path[d] = '/';
334	  memcpy(path + d + 1u, name, strlen(name) + 1u);
335	}
336	
337	/* 从 dNNN_YYYYMMDD_HHMMSS.txt 里取日历戳（形状同 coredump 的 nNNN_...，只换前缀）。
338	 * 无 sscanf：手工解析固定宽度。
339	 *
340	 * 索引要按实际布局数：'d' + NNN + '_' 占 0..4，所以年月日时分秒从 5 开始 ——
341	 * 5..8 / 9..10 / 11..12 / 13='_' / 14..15 / 16..17 / 18..19，20..23 是 ".txt"。
342	 * 早先这里按 4 起算，把 '_' 当数字读，于是**每个**文件都解析失败、清理永不触发
343	 * （"最多 10 条"形同虚设）。降级名 dNNN.txt 记为 0（最老），规则同 coredump。 */
344	
345	static bool diaglog_name_stamp(const char *name, long *stamp)
346	{
347	  static const unsigned pos[6] = { 5u, 9u, 11u, 14u, 16u, 18u }; /* yyyy mm dd hh mm ss */
348	  static const unsigned wid[6] = { 4u, 2u, 2u, 2u, 2u, 2u };
349	  size_t                len;
350	  unsigned              i;
351	  long                  v = 0;
352	
353	  if (name == NULL || name[0] != 'd')
354	    {
355	      return false;
356	    }
357	
358	  len = strlen(name);
359	  if (len < 8u || memcmp(name + len - 4u, ".txt", 4u) != 0)
360	    {
361	      return false;
362	    }
363	
364	  if (len < 24u)
365	    {
366	      *stamp = 0;                /* dNNN.txt —— 没有日历戳，当最老 */
367	      return true;
368	    }
369	
370	  for (i = 0; i < 6u; i++)
371	    {
372	      unsigned j;
373	      long     acc = 0;
374	
375	      for (j = 0; j < wid[i]; j++)
376	        {
377	          char c = name[pos[i] + j];
378	
379	          if (c < '0' || c > '9')
380	            {
381	              return false;
382	            }
383	
384	          acc = acc * 10L + (long)(c - '0');
385	        }
386	
387	      v = v * 10000L + acc;
388	    }
389	
390	  *stamp = v;
391	  return true;
392	}
393	
394	/****************************************************************************
395	 * syslog channel：只搬字节进 RAM 环
396	 ****************************************************************************/
397	
398	static int diaglog_putc(FAR syslog_channel_t *channel, int ch)
399	{
400	  irqstate_t flags;
401	
402	  (void)channel;
403	
404	  flags = up_irq_save();
405	  diaglog_feed((unsigned char)ch);
406	  up_irq_restore(flags);
407	  return ch;
408	}
409	
410	static ssize_t diaglog_write(FAR syslog_channel_t *channel,
411	                             FAR const char *buf, size_t len)
412	{
413	  irqstate_t flags;
414	  size_t     i;
415	
416	  (void)channel;
417	
418	  if (buf == NULL || len == 0)
419	    {
420	      return 0;
421	    }
422	
423	  /* 整块在一个关中断区里过过滤器：状态机（行首缓冲、判定、转义中）是全局的，
424	   * 拆开处理会让别的上下文插进来把行切乱。
425	   * 代价是关中断时间与 len 成正比，但这里一次最多一条 syslog 行（几十~几百字节，
426	   * 240 MHz 下是微秒级），且**不关中断也不碰任何存储** —— 与"注册一个会阻塞在
427	   * SD 卡上的文件通道"是根本不同的量级。 */
428	  flags = up_irq_save();
429	  for (i = 0; i < len; i++)
430	    {
431	      diaglog_feed((unsigned char)buf[i]);
432	    }
433	
434	  up_irq_restore(flags);
435	  return (ssize_t)len;
436	}
437	
438	/* sc_flush 由 NuttX 在崩溃路径上调。这里**刻意什么都不做**：RAM 环没有
439	 * "缓冲待刷"的概念，而在 panic 上下文里去走文件系统是危险的。真正的崩溃落盘
440	 * 交给 coredump 那条已验证的裸 LittleFS 路径，它通过
441	 * myvendor_diaglog_snapshot() 取环内容一起写出去。 */
442	
443	static int diaglog_noop_flush(FAR syslog_channel_t *channel)
444	{
445	  (void)channel;
446	  return 0;
447	}
448	
449	static const struct syslog_channel_ops_s g_diaglog_ops =
450	{
451	  .sc_putc        = diaglog_putc,
452	  .sc_flush       = diaglog_noop_flush,
453	  .sc_write       = diaglog_write,
454	  .sc_write_force = diaglog_write,   /* 中断上下文走同一条：只搬 RAM */
455	};
456	
457	static struct syslog_channel_s g_diaglog_channel =
458	{
459	  .sc_ops = &g_diaglog_ops,
460	};
