462	/****************************************************************************
463	 * 清理：只处理 d* 文件，超过 DIAGLOG_KEEP 删最旧（形状同 coredump）
464	 ****************************************************************************/
465	
466	static bool diaglog_drop_oldest(void)
467	{
468	  DIR           *dir;
469	  struct dirent *de;
470	  char           oldest[DIAGLOG_NAME_MAX];
471	  long           oldest_stamp = LONG_MAX;
472	  bool           have = false;
473	
474	  dir = opendir(DIAGLOG_DIR);
475	  if (dir == NULL)
476	    {
477	      return false;
478	    }
479	
480	  oldest[0] = '\0';
481	  while ((de = readdir(dir)) != NULL)
482	    {
483	      long stamp;
484	
485	      if (de->d_name[0] != 'd' || !diaglog_name_stamp(de->d_name, &stamp))
486	        {
487	          continue;
488	        }
489	
490	      /* 哨兵用 LONG_MAX 而不是 0：降级名 dNNN.txt 的戳就是 0，
491	       * 用 0 当初值会让"还没遇到任何文件"和"遇到最老文件"混淆。 */
492	      if (!have || stamp < oldest_stamp ||
493	          (stamp == oldest_stamp && strcmp(de->d_name, oldest) < 0))
494	        {
495	          have = true;
496	          oldest_stamp = stamp;
497	          memcpy(oldest, de->d_name, sizeof(oldest) - 1u);
498	          oldest[sizeof(oldest) - 1u] = '\0';
499	        }
500	    }
501	
502	  closedir(dir);
503	
504	  if (oldest[0] == '\0')
505	    {
506	      return false;
507	    }
508	
509	  {
510	    char path[DIAGLOG_PATH_MAX];
511	
512	    diaglog_mkpath(path, sizeof(path), oldest);
513	    if (path[0] == '\0')
514	      {
515	        return false;
516	      }
517	
518	    return (unlink(path) == 0);
519	  }
520	}
521	
522	static void diaglog_prune(void)
523	{
524	  unsigned      count = 0;
525	  DIR          *dir;
526	  struct dirent *de;
527	
528	  dir = opendir(DIAGLOG_DIR);
529	  if (dir == NULL)
530	    {
531	      return;
532	    }
533	
534	  while ((de = readdir(dir)) != NULL)
535	    {
536	      long stamp;
537	
538	      if (de->d_name[0] == 'd' && diaglog_name_stamp(de->d_name, &stamp))
539	        {
540	          count++;
541	        }
542	    }
543	
544	  closedir(dir);
545	
546	  while (count > DIAGLOG_KEEP)
547	    {
548	      if (!diaglog_drop_oldest())
549	        {
550	          break;
551	        }
552	
553	      count--;
554	    }
555	}
556	
557	/****************************************************************************
558	 * seq：一个序号文件记"开机第几次日志"（本目录自己的，与 coredump 的 seq 无关）
559	 ****************************************************************************/
560	
561	static unsigned diaglog_next_seq(void)
562	{
563	  const char *seq_path = DIAGLOG_DIR "/seq";
564	  char        buf[16];
565	  int         fd;
566	  ssize_t     n;
567	  unsigned    v = 0;
568	  unsigned    i;
569	
570	  fd = open(seq_path, O_RDONLY);
571	  if (fd >= 0)
572	    {
573	      n = read(fd, buf, sizeof(buf) - 1u);
574	      close(fd);
575	      if (n > 0)
576	        {
577	          buf[n] = '\0';
578	          for (i = 0; i < (unsigned)n && buf[i] >= '0' && buf[i] <= '9'; i++)
579	            {
580	              v = v * 10u + (unsigned)(buf[i] - '0');
581	            }
582	        }
583	    }
584	
585	  v = (v + 1u) % (DIAGLOG_SEQ_MAX + 1u);
586	
587	  {
588	    char *p;
589	
590	    p = diaglog_put_u(buf, v, 3u);
591	    *p++ = '\n';
592	
593	    fd = open(seq_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
594	    if (fd >= 0)
595	      {
596	        (void)write(fd, buf, (size_t)(p - buf));
597	        close(fd);
598	      }
599	  }
600	
601	  return v;
602	}
603	
604	/****************************************************************************
605	 * Public Functions
606	 ****************************************************************************/
607	
608	int myvendor_diaglog_start(void)
609	{
610	  unsigned seq;
611	  time_t   now = time(NULL);
612	  char     name[DIAGLOG_NAME_MAX];
613	  int      ret;
614	
615	  if (g_started)
616	    {
617	      return 0;
618	    }
619	
620	  /* 目录现在是自己独占的，没有别人会先建它 —— 这里必须真的建出来。 */
621	  ret = mkdir(DIAGLOG_DIR, 0755);
622	  if (ret < 0 && errno != EEXIST)
623	    {
624	      return -errno;
625	    }
626	
627	  seq = diaglog_next_seq();
