651	int myvendor_diaglog_flush(void)
652	{
653	  irqstate_t flags;
654	  uint32_t   head;
655	  uint32_t   tail;
656	  int        fd;
657	
658	  if (!g_started)
659	    {
660	      return -EAGAIN;
661	    }
662	
663	  /* 按天滚动：跨天后换一个文件（同一次开机也就有了"一天一个"）。 */
664	  {
665	    time_t    now = time(NULL);
666	    struct tm tm;
667	
668	    localtime_r(&now, &tm);
669	    if (tm.tm_yday != g_day)
670	      {
671	        char name[DIAGLOG_NAME_MAX];
672	
673	        diaglog_mkname(name, sizeof(name), diaglog_next_seq(), now);
674	        diaglog_mkpath(g_path, sizeof(g_path), name);
675	        diaglog_prune();
676	      }
677	  }
678	
679	  flags = up_irq_save();
680	  head = g_head;
681	  tail = g_tail;
682	  up_irq_restore(flags);
683	
684	  if (head == tail)
685	    {
686	      return 0;
687	    }
688	
689	  fd = open(g_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
690	  if (fd < 0)
691	    {
692	      int err = errno;
693	
694	      /* 写不了就保留在环里，下次再试；绝不因为日志失败去格式化或复位。
695	       * 首次失败报一行（之后静默）—— 否则"完全没落盘"会无声无息，
696	       * 那正是这套东西要解决的毛病。errno 先存下来，syslog 会改它。 */
697	      if (!g_fail_logged)
698	        {
699	          g_fail_logged = true;
700	          syslog(LOG_ERR, "diaglog: flush open failed %d, keep in ring\n", err);
701	        }
702	
703	      return -err;
704	    }
705	
706	  /* 一直写到环空为止，但受 DIAGLOG_WRITE_MAX 总预算约束。
707	   *
708	   * 早先的版本每个 tick 只写 2048 B（约 400 B/s），而实测活跃期日志速率是
709	   * 2~4 KB/s —— 入不敷出，环会长期满着、持续丢最新几行。现在按预算尽量写到空：
710	   * 正常速率下环几乎总是空的（内容基本立刻落盘），只有刷屏期才会丢，
711	   * 这也正是"尽量落盘、大量异常就算了"的语义。
712	   *
713	   * 每轮重新取 head，才能把本轮写入期间新产生的日志也一起带走。 */
714	
715	  {
716	    int total = 0;
717	
718	    while (total < (int)DIAGLOG_WRITE_MAX)
719	      {
720	        uint32_t n;
721	        ssize_t  nw;
722	
723	        flags = up_irq_save();
724	        head = g_head;
725	        tail = g_tail;
726	        up_irq_restore(flags);
727	
728	        if (head == tail)
729	          {
730	            break;
731	          }
732	
733	        n = (head > tail) ? (head - tail) : (DIAGLOG_RING - tail);
734	        if (n > (uint32_t)((int)DIAGLOG_WRITE_MAX - total))
735	          {
736	            n = (uint32_t)((int)DIAGLOG_WRITE_MAX - total);
737	          }
738	
739	        nw = write(fd, &g_ring[tail], n);
740	        if (nw <= 0)
741	          {
742	            if (total == 0)
743	              {
744	                close(fd);
745	                return (nw == 0) ? 0 : -errno;
746	              }
747	
748	            break;
749	          }
750	
751	        flags = up_irq_save();
752	        g_tail = (g_tail + (uint32_t)nw) % DIAGLOG_RING;
753	        up_irq_restore(flags);
754	        total += (int)nw;
755	      }
756	
757	    close(fd);
758	    return total;
759	  }
760	}
