771	size_t myvendor_diaglog_pending(void)
772	{
773	  irqstate_t flags;
774	  uint32_t   head;
775	  uint32_t   tail;
776	
777	  flags = up_irq_save();
778	  head = g_head;
779	  tail = g_tail;
