786	size_t myvendor_diaglog_snapshot(char *out, size_t n)
787	{
788	  uint32_t head;
789	  uint32_t tail;
790	  size_t   used = 0;
791	
792	  if (out == NULL || n < 2u)
793	    {
794	      return 0;
795	    }
796	
797	  head = g_head;
798	  tail = g_tail;
799	  if (head == tail)
800	    {
801	      out[0] = '\0';
802	      return 0;
803	    }
804	
805	  /* 从 tail 到 head，按时间顺序拷出来。只做内存拷贝，可以在很差的环境里调用。 */
806	  while (tail != head && used + 1u < n)
807	    {
808	      out[used++] = g_ring[tail];
809	      tail = (tail + 1u) % DIAGLOG_RING;
810	    }
811	
812	  out[used] = '\0';
813	  return used;
814	}
