118	+/* ===== DWT 周期计数器：给读线程用的、与 tick 无关的时间基准 ==============
119	+ *
120	+ * 背景（docs/gnss_ble_diag_log.md §2.2）：读线程原先用 `poll(…, timeout_ms)`
121	+ * 等数据，而 `poll()` 的超时是**由 tick 驱动的看门狗**。一旦计时基准被打断
122	+ * （§2.2 点名的 `up_timer_set_lowerhalf()` 型故障），这个超时不再到期，
123	+ * 线程就永久停在 `poll()` 里：`pthread_cancel` 唤不醒它（阻塞在系统调用），
124	+ * reap 只能放弃 join，于是 `g_gnss_stack_busy` 永远为 1、spawn 永远被拒 ——
125	+ * GNSS 直到关机都不恢复（现场 hb_age 一路涨到 261 s）。
126	+ *
127	+ * DWT_CYCCNT 是 CPU 自由运行的周期计数器，**不经过 SysTick，也不挂 wdog**，
128	+ * 所以拿它做等待的上界不会被上面那类故障打断。它只用于"到点该返回了"的判断，
129	+ * 不参与任何状态机；`sched_yield()` 让出 CPU，睡眠仍由 idle 的 WFI 承担。
130	+ *
131	+ * CYCCNT 需要 TRCENA + CYCCNTENA，不保证每颗芯片都真的在跑；所以初始化时
132	+ * 做一次自检（两次读数必须不同），跑不起来就整体退回 `usleep()` 老路径 ——
133	+ * 有降级，但不会因为读一个不动的时间戳而算错等待。
134	+ */
135	+#define GNSS_DWT_DEMCR   (*(volatile uint32_t *)0xe000edfcu)
136	+#define GNSS_DWT_CTRL    (*(volatile uint32_t *)0xe0001000u)
137	+#define GNSS_DWT_CYCCNT  (*(volatile uint32_t *)0xe0001004u)
138	+/* Armv8-M（本板是 Cortex-M33）的 DWT 是锁访问的：不解锁的话往 CTRL/CYCCNT
139	+ * 写全被忽略，CYCCNT 永远不动。解锁值固定是 0xC5ACCE55。
140	+ *
141	+ * 两个 LAR 都写：0xe0001fb0 是 Armv8-M 架构规定的 **DWT_LAR**，0xe0000fb0 是
142	+ * ITM_LAR。本板既有的 DWT 用户（chips/sf32lb52/myvendor_idle_stat.c 的
143	+ * myvendor_dwt_init()）只写了 ITM_LAR 且实测可用（up_idle() 每次进 idle 都
144	+ * 用 CYCCNT 记 WFI 时长，统计是正常的），说明这颗片子两个锁要么共享、
145	+ * 要么根本没锁。两个都写一遍，无论哪种情况都能解锁，且都是幂等的。 */
146	+#define GNSS_DWT_LAR     (*(volatile uint32_t *)0xe0001fb0u)
147	+#define GNSS_ITM_LAR     (*(volatile uint32_t *)0xe0000fb0u)
148	+#define GNSS_DWT_LAR_KEY 0xc5acce55u
149	+
150	+/* CMSIS 定义在别处（sifli_systick_reclock() 会跟着 HCLK 更新它）。 */
151	+extern uint32_t SystemCoreClock;
152	+
153	+static bool g_dwt_ready;
154	+static bool g_dwt_usable;   /* CYCCNT 自检通过，可当时间基准 */
155	+
156	+static void gnss_dwt_init_once(void)
157	+{
158	+  uint32_t a;
159	+  uint32_t b;
160	+  int i;
161	+
162	+  if (g_dwt_ready)
163	+    {
164	+      return;
165	+    }
166	+
167	+  g_dwt_ready = true;
168	+
169	+  GNSS_ITM_LAR = GNSS_DWT_LAR_KEY;   /* 与本板既有 idle_stat 的写法一致 */
170	+  GNSS_DWT_LAR = GNSS_DWT_LAR_KEY;   /* Armv8-M 架构规定的 DWT_LAR */
171	+  GNSS_DWT_DEMCR |= (1u << 24);      /* TRCENA —— 使能跟踪子系统 */
172	+  GNSS_DWT_CTRL |= 1u;               /* CYCCNTENA */
173	+
174	+  /* 注意：**不要**清零 GNSS_DWT_CYCCNT。
175	+   *
176	+   * CYCCNT 是全系统共享的：chips/sf32lb52/myvendor_idle_stat.c 用它统计 WFI
177	+   * 占比，窗口起点存在 g_win_start_cyc 里，用 `now - start` 的 uint32 回绕差
178	+   * 算时长。在它的窗口中间把计数器清零，会让那一个窗口的统计直接失准。
179	+   * 本文件只用差值（now - cyc0），不需要从 0 开始，所以没有理由去动它。 */
180	+
181	+  /* 自检：读数必须会变，否则它只是个恒定的 MMIO 寄存器。 */
182	+  a = GNSS_DWT_CYCCNT;
183	+  for (i = 0; i < 64; i++)
184	+    {
185	+      __asm__ volatile("nop");
186	+    }
187	+
188	+  b = GNSS_DWT_CYCCNT;
189	+  g_dwt_usable = (b != a);
190	+
191	+  if (!g_dwt_usable)
192	+    {
193	+      syslog(LOG_WARNING,
194	+             "gnss: DWT CYCCNT 不可用，读等待退回 usleep\n");
195	+    }
196	+}
197	+
198	+static inline uint32_t gnss_cycles_now(void)
199	+{
200	+  return GNSS_DWT_CYCCNT;
201	+}
