203	+/** @return 微秒预算对应的周期数；DWT / HCLK 不可用时返回 0（表示"别用 DWT 判超时"）。 */
204	+static uint32_t gnss_cycles_budget_us(uint32_t us)
205	+{
206	+  uint32_t hz = SystemCoreClock;
207	+
208	+  if (!g_dwt_usable || hz == 0)
209	+    {
210	+      return 0;
211	+    }
212	+
213	+  return (uint32_t)(((uint64_t)us * (uint64_t)hz) / 1000000u);
214	+}
