216	+/** 让出 CPU 给所有就绪任务（含更低优先级），定义见下。 */
217	+static void gnss_yield_all(const struct sched_param *restore, int policy,
218	+                           bool have);
219	+
220	+/**
221	+ * @brief 与 tick 无关的短睡眠（微秒）。
222	+ *
223	+ * `usleep()` 内部同样要挂一个 wdog 超时，所以 §2.2 那类故障下它也会一起失灵：
224	+ * 线程卡在睡眠里，连 `g_gnss_stop` 都看不到，reap 照样只能放弃。读线程上的
225	+ * 每一处等待都必须是"一定会醒"的，所以这些短睡眠统一走 DWT 预算 +
226	+ * `sched_yield()`：睡眠由 idle 的 WFI 承担，上界由 DWT 保证，全程不碰 wdog。
227	+ *
228	+ * @param us 微秒。0、或 DWT/HCLK 不可用时退回原来的 `usleep()`。
229	+ * @note 语义是"至少睡够"。按时基粒度（100 Hz）取整，只会偏长不会偏短 ——
230	+ *       调用方需要的是最小间隔（星历帧间隙、上电稳定时间），偏长是安全的。
231	+ * @note 这是自旋实现，**会烧 CPU**：调用点都是低频路径（写退避、星历帧
232	+ *       间隙、VCC 稳定时间），所以代价可接受；但像
233	+ *       `gnss_sleep_ms(CONFIG_BOARD_L96_GNSS_PWR_DELAY_MS)`（可达 1 s）
234	+ *       这样的长睡眠仍是实打实的一秒 CPU。**稳态等待路径不走这里**
235	+ *       —— 那一条已经改成阻塞 `poll()`，见 `gnss_read_some()`。
236	+ */
237	+static void gnss_sleep_us(uint32_t us)
238	+{
239	+  uint32_t budget;
240	+  uint32_t cyc0;
241	+  uint32_t spins = 0;
242	+  struct sched_param prio0;
243	+  int policy0 = 0;
244	+  bool have0;
245	+
246	+  if (us == 0)
247	+    {
248	+      return;
249	+    }
250	+
251	+  budget = gnss_cycles_budget_us(us);
252	+  if (budget == 0)
253	+    {
254	+      usleep(us);
255	+      return;
256	+    }
257	+
258	+  /* 原优先级在**入口取一次**，不在自旋循环里取。
259	+   *
260	+   * 循环里取到的是"我们刚刚降下去的最低优先级"，于是 low=1、恢复也回 1 ——
261	+   * 一次恢复失败就会把最低优先级当成原值永久固化（`ps` 里看到的
262	+   * `gnss pri=1`）。在入口取就没有这个自我引用的机会。 */
263	+  have0 = (pthread_getschedparam(pthread_self(), &policy0, &prio0) == 0);
264	+
265	+  cyc0 = gnss_cycles_now();
266	+  for (;;)
267	+    {
268	+      if ((uint32_t)(gnss_cycles_now() - cyc0) >= budget)
269	+        {
270	+          return;
271	+        }
272	+
273	+      if (++spins > GNSS_SLEEP_SPIN_MAX)
274	+        {
275	+          return;
276	+        }
277	+
278	+      if ((spins % GNSS_SPIN_YIELD_EVERY) == 0u)
279	+        {
280	+          gnss_yield_all(&prio0, policy0, have0);  /* 别饿住 diag / BT LW WQ */
281	+        }
282	+      else
283	+        {
284	+          (void)sched_yield();
285	+        }
286	+    }
287	+}
288	+
289	+static void gnss_sleep_ms(uint32_t ms)
290	+{
291	+  gnss_sleep_us(ms * 1000u);
292	+}
