294	+/**
295	+ * @brief 把 CPU 让给**所有**其它就绪任务，包括优先级比本线程低的。
296	+ *
297	+ * `sched_yield()` 做不到这一点：它等价于把本线程重新排到"同优先级"的队尾
298	+ * （`nuttx/sched/sched_yield.c` 的注释写得很清楚），所以优先级低于本线程的
299	+ * 任务在自旋期间一个都跑不到。
300	+ *
301	+ * 本 fork 里**数值越大优先级越高**（`SCHED_PRIORITY_MAX`=255 是最高，
302	+ * `SCHED_PRIORITY_MIN`=1 是最低；佐证：hpwork=224 > lpwork=100，
303	+ * "BT LW WQ"=10，diag=9，gnss=50，ui_flush=100）。读线程 prio=50，
304	+ * 所以它的自旋会饿住优先级比它低的两条关键路径：
305	+ *   - `diag`     prio 9  —— GNSS 的判死 / 重启全靠它；
306	+ *   - `BT LW WQ` prio 10 —— zblue 的延迟工作队列，蓝牙的收尾工作靠它。
307	+ * 这两条都必须能秒级被调度到（diag 被饿住就等于自愈能力被拿掉，
308	+ * 正是「连上了但一直未连接」那类问题的放大版），所以自旋期间必须定期
309	+ * 把 CPU 真正交出去。
310	+ *
311	+ * 做法：临时降到最低优先级再让出 —— 这样所有就绪任务都会排到我们前面，
312	+ * 等我们下次被调度回来时立刻恢复原优先级。
313	+ *
314	+ * @param restore 调用方在**自旋之前**取好的原优先级。
315	+ * @param policy  与 `restore` 配套的调度策略。
316	+ * @param have    `false` 表示取原优先级失败，此时只做 `sched_yield()`。
317	+ *
318	+ * @warning **不要在这里用 `pthread_getschedparam()` 取原优先级。**
319	+ *          循环里读到的值是"我们刚降下去的最低优先级"，于是恢复也回最低 ——
320	+ *          一次恢复失败（或读到被降过的值）就会把最低优先级当成原值永久
321	+ *          固化，`ps` 里看到读线程常年 `pri=1` 就是这么来的。
322	+ *          原值必须由调用方在进入自旋前捕获一次。
323	+ */
324	+static void gnss_yield_all(const struct sched_param *restore, int policy,
325	+                           bool have)
326	+{
327	+  struct sched_param low;
328	+
329	+  if (!have || restore == NULL)
330	+    {
331	+      (void)sched_yield();
332	+      return;
333	+    }
334	+
335	+  low = *restore;
336	+  low.sched_priority = SCHED_PRIORITY_MIN;
337	+
338	+  /* 降优先级本身就会触发重调度：只要 diag / BT LW WQ 就绪，我们马上被换下。
339	+   * 那句 sched_yield() 只是兜底（万一同优先级还有别的就绪任务）。 */
340	+  if (pthread_setschedparam(pthread_self(), policy, &low) == 0)
341	+    {
342	+      (void)sched_yield();
343	+      (void)pthread_setschedparam(pthread_self(), policy, restore);
344	+    }
345	+  else
346	+    {
347	+      (void)sched_yield();
348	+    }
349	+}
