#ifdef CONFIG_MYVENDOR_GNSS_LOG
        g_poll_to_run++;
        if ((g_poll_to_run % 10u) == 0u) {
          GNSS_LOG("poll_to run=%u fd=%d", (unsigned)g_poll_to_run, fd);
        }
#endif
      }

      return 0;
    }

    return -errno;
  }

  if (n == 0) {
    if (pr == 0) {
      gnss_link_add(&g_link.poll_to);
#ifdef CONFIG_MYVENDOR_GNSS_LOG
      g_poll_to_run++;
      if ((g_poll_to_run % 10u) == 0u) {
        GNSS_LOG("poll_to run=%u fd=%d", (unsigned)g_poll_to_run, fd);
      }
#endif
      return 0;
    }

    return -EIO;
  }

#ifdef CONFIG_MYVENDOR_GNSS_LOG
  g_poll_to_run = 0;
#endif
  gnss_link_add(&g_link.rd);
  gnss_link_note(&g_link.byte, (uint16_t)n);
  return (int)n;
}

